Example
● Register an operator tiling structure.
#include "register/tilingdata_base.h"
// Define the TilingData class.
namespace optiling {
BEGIN_TILING_DATA_DEF(AddCustomTilingData)    // Register a tiling class and uses the tiling name
as the input parameter.
TILING_DATA_FIELD_DEF(uint32_t, blkDim);    // Add a tiling field to compute the number of cores.
TILING_DATA_FIELD_DEF(uint32_t, totalSize); // Add a tiling field to compute the total data size.
TILING_DATA_FIELD_DEF(uint32_t, splitTile); // Add a tiling field and compute data processed by
each core by block.
END_TILING_DATA_DEF;                          // Definition ends.
// Register the operator TilingData class with the corresponding AddCustom operator.
REGISTER_TILING_DATA_CLASS(AddCustom, AddCustomTilingData)
}
● Register an intermediate structure. In structure nesting scenarios, the nested
structure is called the intermediate structure. Since only one tiling structure
can be registered for a given operator name, in order for the framework to
detect intermediate structure information, it is necessary to construct a
'virtual operator name' (structure name + Op) and register the intermediate
structure through the REGISTER_TILING_DATA_CLASS API. The registration
method is as follows:
BEGIN_TILING_DATA_DEF(Matmul)
TILING_DATA_FIELD_DEF(uint16_t, mmVar);
TILING_DATA_FIELD_DEF_ARR(uint16_t, 3, mmArr);
END_TILING_DATA_DEF;
// Register an intermediate structure. The first parameter is fixed to struct_name#Op, and the second
parameter is struct_name. For example, if struct_name is Matmul, the first parameter is MatmulOp
and the second parameter is Matmul.
REGISTER_TILING_DATA_CLASS(MatmulOp, Matmul)      // Register an intermediate structure.
