static ge::graphStatus OpSelectFormat(const ge::Operator &op, ge::AscendString &result)
{
std::string resultJsonStr;
// If the first dimension of the first input parameter's shape is less than or equal to 8, multiple formats
are supported. Otherwise, only int32 is supported.
if (op.GetInputDesc(0).GetShape().GetDim(0) <= 8) {
resultJsonStr = R"({
"input0": {"name": "x","dtype": "float16,float32,int32","format": "ND,ND,ND","unknownshape_format":
"ND,ND,ND"},
"input1": {"name": "y","dtype": "float16,float32,int32","format": "ND,ND,ND","unknownshape_format":
"ND,ND,ND"},
"output0": {"name": "z","dtype": "float16,float32,int32","format":
"ND,ND,ND","unknownshape_format": "ND,ND,ND"}
})";
} else {
resultJsonStr = R"({
"input0": {"name": "x","dtype": "int32","format": "ND","unknownshape_format": "ND"},
"input1": {"name": "y","dtype": "int32","format": "ND","unknownshape_format": "ND"},
"output0": {"name": "z","dtype": "int32","format": "ND","unknownshape_format": "ND"}
})";
